'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var isCollection = require( '@stdlib/assert/is-collection' );
var resolveGetter = require( '@stdlib/array/base/resolve-getter' );
var iteratorSymbol = require( '@stdlib/symbol/iterator' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns an iterator which iterates over the Cartesian square of an array-like object.
*
* ## Notes
*
* -   The Cartesian square is equivalent to the Cartesian product of an array-like object with itself.
* -   The order of the returned tuples follows the order of iteration of the provided array-like object, with elements of the second tuple component varying fastest.
* -   If provided an empty array-like object, the returned iterator is empty.
* -   If an environment supports `Symbol.iterator`, the returned iterator is iterable.
*
* @param {Collection} x - input array
* @throws {TypeError} argument must be an array-like object
* @returns {Iterator} iterator
*
* @example
* var iter = iterCartesianSquare( [ 1, 2 ] );
*
* var v = iter.next().value;
* // returns [ 1, 1 ]
*
* v = iter.next().value;
* // returns [ 1, 2 ]
*
* v = iter.next().value;
* // returns [ 2, 1 ]
*
* // ...
*/
function iterCartesianSquare( x ) {
	var iter;
	var get;
	var FLG;
	var N;
	var i;
	var j;

	if ( !isCollection( x ) ) {
		throw new TypeError( format( 'invalid argument. Argument must be an array-like object. Value: `%s`.', x ) );
	}
	get = resolveGetter( x );
	N = x.length;
	i = 0;
	j = 0;

	// Create an iterator protocol-compliant object:
	iter = {};
	setReadOnly( iter, 'next', next );
	setReadOnly( iter, 'return', end );

	// If an environment supports `Symbol.iterator`, make the iterator iterable:
	if ( iteratorSymbol ) {
		setReadOnly( iter, iteratorSymbol, factory );
	}
	return iter;

	/**
	* Returns an iterator protocol-compliant object containing the next iterated value.
	*
	* @private
	* @returns {Object} iterator protocol-compliant object
	*/
	function next() {
		var v;
		if ( FLG || N === 0 || i >= N ) {
			return {
				'done': true
			};
		}
		v = [ get( x, i ), get( x, j ) ];

		// Update the indices for the next iteration:
		j += 1;
		if ( j >= N ) {
			j = 0;
			i += 1;
		}
		return {
			'value': v,
			'done': false
		};
	}

	/**
	* Finishes an iterator.
	*
	* @private
	* @param {*} [value] - value to return
	* @returns {Object} iterator protocol-compliant object
	*/
	function end( value ) {
		FLG = true;
		if ( arguments.length ) {
			return {
				'value': value,
				'done': true
			};
		}
		return {
			'done': true
		};
	}

	/**
	* Returns a new iterator.
	*
	* @private
	* @returns {Iterator} iterator
	*/
	function factory() {
		return iterCartesianSquare( x );
	}
}


// EXPORTS //

module.exports = iterCartesianSquare;
